--
-- Name: get_diameters(); Type: FUNCTION; Schema: metric; Owner: -
--

CREATE FUNCTION metric.get_diameters() RETURNS TABLE(id bigint, diameter double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN


    RETURN QUERY EXECUTE format(
        'SELECT id, diameter FROM metric.main'    );
END;
$$;


--
-- Name: get_diameters(text); Type: FUNCTION; Schema: metric; Owner: -
--

CREATE FUNCTION metric.get_diameters(order_direction text) RETURNS TABLE(id bigint, text character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Проверяем корректность аргумента order_direction
    IF order_direction NOT IN ('ASC', 'DESC') THEN
        RAISE EXCEPTION 'Invalid order direction. Use ''ASC'' or ''DESC''.';
    END IF;

    -- Выполняем запрос с динамическим указанием направления сортировки
    RETURN QUERY EXECUTE format(
        'SELECT id, format(''M %%s'', diameter)::character varying AS text FROM metric.main ORDER BY diameter %s',
        order_direction
    );
END;
$$;


--
-- Name: update_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;


